CREATE OR REPLACE FUNCTION public.add_exp(p_member_id uuid, p_amount integer, p_reason text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  update public.members set exp_tokens = exp_tokens + p_amount where id = p_member_id;
  insert into public.exp_events (member_id, amount, reason) values (p_member_id, p_amount, p_reason);
end;
$function$
